mapper.select:
SELECT p.id, p.merchant_id, m.name as merchant_name, p.category_id, c.name as category_name, p.name, p.type, CASE WHEN p.type = 'PHYSICAL' THEN '实物商品' WHEN p.type = 'SERVICE' THEN '服务商品' ELSE '未知类型' END as type_desc, p.status, CASE WHEN p.status = 'DRAFT' THEN '草稿' WHEN p.status = 'PUBLISHED' THEN '已发布' WHEN p.status = 'ARCHIVED' THEN '已归档' ELSE '未知状态' END as status_desc, p.tags, p.description, p.main_image, p.sort_weight, COALESCE(sku_info.min_price, 0) as min_price, COALESCE(sku_info.max_price, 0) as max_price, COALESCE(sku_info.total_stock, 0) as total_stock, COALESCE(sku_info.sku_count, 0) as sku_count, COALESCE(sales_info.total_sales, 0) as total_sales, p.created_by, p.updated_by, p.created_time, p.updated_time FROM products p LEFT JOIN product_categories c ON p.category_id = c.id LEFT JOIN merchants m on p.merchant_id = m.id LEFT JOIN ( SELECT product_id, MIN(price) as min_price, MAX(price) as max_price, SUM(CASE WHEN stock = -1 THEN 999999 ELSE stock END) as total_stock, COUNT(*) as sku_count FROM product_skus WHERE is_deleted = 0 GROUP BY product_id ) sku_info ON p.id = sku_info.product_id LEFT JOIN ( SELECT oi.product_id, SUM(oi.quantity) as total_sales FROM order_items oi JOIN orders o ON oi.order_id = o.id WHERE o.status IN ('PAID', 'PENDING_VERIFICATION', 'COMPLETED') AND o.is_deleted = 0 AND oi.is_deleted = 0 GROUP BY oi.product_id ) sales_info ON p.id = sales_info.product_id WHERE p.is_deleted = 0
AND p.merchant_id = #{query.merchantId}
AND p.category_id = #{query.categoryId}
AND p.name LIKE CONCAT('%', #{query.name}, '%')
AND p.type = #{query.type}
AND p.status = #{query.status}
AND JSON_SEARCH(p.tags, 'one', CONCAT('%', #{query.tag}, '%')) IS NOT NULL
AND p.created_time >= #{query.createdStart}
AND p.created_time <= #{query.createdEnd}
ORDER BY
p.updated_time p.created_time p.sort_weight p.name p.updated_time
ASC DESC
ORDER BY p.updated_time DESC

SELECT p.id, p.merchant_id, p.category_id, c.name as category_name, p.name, p.type, CASE WHEN p.type = 'PHYSICAL' THEN '实物商品' WHEN p.type = 'SERVICE' THEN '服务商品' ELSE '未知类型' END as type_desc, p.status, CASE WHEN p.status = 'DRAFT' THEN '草稿' WHEN p.status = 'PUBLISHED' THEN '已发布' WHEN p.status = 'ARCHIVED' THEN '已归档' ELSE '未知状态' END as status_desc, p.tags, p.description, p.main_image, p.sort_weight, COALESCE(sku_info.min_price, 0) as min_price, COALESCE(sku_info.max_price, 0) as max_price, COALESCE(sku_info.total_stock, 0) as total_stock, COALESCE(sku_info.sku_count, 0) as sku_count, COALESCE(sales_info.total_sales, 0) as total_sales, p.created_by, p.updated_by, p.created_time, p.updated_time FROM products p LEFT JOIN product_categories c ON p.category_id = c.id LEFT JOIN ( SELECT product_id, MIN(price) as min_price, MAX(price) as max_price, SUM(CASE WHEN stock = -1 THEN 999999 ELSE stock END) as total_stock, COUNT(*) as sku_count FROM product_skus WHERE is_deleted = 0 GROUP BY product_id ) sku_info ON p.id = sku_info.product_id LEFT JOIN ( SELECT oi.product_id, SUM(oi.quantity) as total_sales FROM order_items oi JOIN orders o ON oi.order_id = o.id WHERE o.status IN ('PAID', 'PENDING_VERIFICATION', 'COMPLETED') AND o.is_deleted = 0 AND oi.is_deleted = 0 GROUP BY oi.product_id ) sales_info ON p.id = sales_info.product_id WHERE p.merchant_id = #{merchantId} AND p.is_deleted = 0
AND p.status = #{status}
ORDER BY p.updated_time DESC

